const ALLOWED_SOURCE_PATHS = new Set([
  '/', '/blog/', '/books/', '/calorie-calculator/', '/join/',
  '/lose-fat-gain-muscle/', '/supplements/'
]);
if (!sourceUrl || !ALLOWED_SOURCE_PATHS.has(sourceUrl)) {
  return { ok: false, status: 400, code: 'invalid_source' };
}
