// verify-dist.mjs, Lines 60-66
const outputText = readdirRecursive(clientRoot)
  .filter((path) => /\.(?:html|xml|txt|css)$/.test(path))
  .map((path) => readFileSync(path, 'utf8'))
  .join('\n');

for (const forbidden of ['jquery', 'bootstrap.min.js', 'popper', 'tippy']) {
  if (outputText.toLowerCase().includes(forbidden.toLowerCase())) {
    fail(`Forbidden output string: ${forbidden}`);
  }
}
